package analyzer

import (
	"fmt"
	"sort"
	"strings"
	"time"

	"clustara/internal/store"
)

// DetectActionAnomalies flags requesters who issued many high/critical-risk K8s actions within a
// short window — a sign of a runaway script or compromised credential (SEC-09 감사 이상 탐지).
func DetectActionAnomalies(actions []store.K8sActionRequest, now time.Time, window time.Duration, threshold int) []SecFinding {
	if threshold < 1 {
		threshold = 5
	}
	byUser := map[string]int{}
	for _, a := range actions {
		if a.RiskLevel != "high" && a.RiskLevel != "critical" {
			continue
		}
		when, err := time.Parse(time.RFC3339Nano, a.CreatedAt)
		if err != nil || now.Sub(when) > window {
			continue
		}
		byUser[firstNonEmptyStr(a.RequestedBy, "(unknown)")]++
	}
	out := []SecFinding{}
	for user, n := range byUser {
		if n >= threshold {
			out = append(out, SecFinding{
				ResourceKind: "User", ResourceName: user, Rule: "audit-action-burst", Severity: "high",
				Message:  fmt.Sprintf("%s가 최근 %s 동안 위험 액션을 %d회 요청했습니다.", user, window.String(), n),
				Evidence: []string{fmt.Sprintf("위험 액션 요청 %d회 (임계 %d)", n, threshold)},
			})
		}
	}
	return out
}

// securityNamespaceKey identifies a namespace inside one cluster. A posture run may span
// clusters, where the same namespace name is a different namespace per cluster.
type securityNamespaceKey struct {
	clusterID string
	namespace string
}

// SecFinding is one security/policy issue (SEC-02/03/04/06).
type SecFinding struct {
	// ClusterID names the cluster the finding came from; empty for findings that are not tied
	// to one (the audit-burst anomaly is per requester). It is omitted from the JSON when
	// empty so single-cluster responses keep their existing shape.
	ClusterID    string   `json:"cluster_id,omitempty"`
	Namespace    string   `json:"namespace"`
	ResourceKind string   `json:"resource_kind"`
	ResourceName string   `json:"resource_name"`
	Rule         string   `json:"rule"`
	Severity     string   `json:"severity"`
	Message      string   `json:"message"`
	Evidence     []string `json:"evidence"`
}

// PodSecurityResult is the Pod Security Standards classification of one workload (SEC-01).
type PodSecurityResult struct {
	ClusterID  string   `json:"cluster_id,omitempty"`
	Namespace  string   `json:"namespace"`
	Kind       string   `json:"kind"`
	Name       string   `json:"name"`
	Level      string   `json:"level"` // restricted | baseline | privileged
	Violations []string `json:"violations"`
}

// SecurityReport is the aggregate posture returned by AnalyzeSecurity.
type SecurityReport struct {
	PodSecurity []PodSecurityResult `json:"pod_security"`
	RBAC        []SecFinding        `json:"rbac"`
	Images      []SecFinding        `json:"images"`
	Secrets     []SecFinding        `json:"secrets"`
	Network     []SecFinding        `json:"network"`
	Summary     SecuritySummary     `json:"summary"`
}

type SecuritySummary struct {
	Workloads    int `json:"workloads"`
	Privileged   int `json:"privileged"`
	Baseline     int `json:"baseline"`
	Restricted   int `json:"restricted"`
	RBACFindings int `json:"rbac_findings"`
	ImageIssues  int `json:"image_issues"`
	case len(baseline) > 0, len(restricted) > 0:
		res.Level = "baseline"
	default:
		res.Level = "restricted"
	}
	return res
}

// restrictedProfileViolations lists the Pod Security "Restricted" controls this pod
// spec fails. It is shared by the posture report and the enforce_pss_restricted
// guardrail so the screen and the admission gate cannot disagree about whether one
// pod meets the standard.
func restrictedProfileViolations(ps map[string]any) []string {
	out := []string{}
	podRunAsNonRoot := asBool(asAnyMap(ps["securityContext"])["runAsNonRoot"])
	for _, raw := range SecurityRelevantContainers(ps) {
		c := asAnyMap(raw)
		sc := asAnyMap(c["securityContext"])
		cname := str(c["name"])
		// A container's securityContext overrides the pod's, so an explicit false on the
		// container means that container runs as root however the pod is configured.
		if set, ok := sc["runAsNonRoot"].(bool); ok {
			if !set {
				out = append(out, cname+": runAsNonRoot=false (Pod 설정을 덮어씀)")
			}
		} else if !podRunAsNonRoot {
			out = append(out, cname+": runAsNonRoot 미설정")
		}
		if !hasKey(sc, "allowPrivilegeEscalation") || asBool(sc["allowPrivilegeEscalation"]) {
			out = append(out, cname+": allowPrivilegeEscalation!=false")
		}
		if !dropsAll(asAnyMap(sc["capabilities"])) {
			out = append(out, cname+": capabilities drop ALL 아님")
		}
	}
	return out
}

func imageFindings(it store.K8sInventoryItem, ps map[string]any) []SecFinding {
	out := []SecFinding{}
	for _, img := range ExtractImages(ps) {
		// Judged with the same parser as the SEC-10 policy gate (disallow_latest_tag), which
		// reads a `:` as a tag only after the last `/`. The substring test this replaces let
		// `registry.corp.local:5000/app` — untagged, so `:latest` as far as the kubelet is
		// concerned — pass the posture check on the strength of its registry port, while the
		// policy gate flagged the very same image. Registries with an explicit port are the
		// norm in the closed networks this product targets.
		tag, digest := imageTagAndDigest(img)
		bad := []string{}
		if digest == "" && (tag == "" || tag == "latest") {
			bad = append(bad, "mutable/누락 태그(:latest 또는 태그 없음)", "digest 고정 안 됨")
		}
		if len(bad) > 0 {
			out = append(out, SecFinding{
				ClusterID: it.ClusterID,
				Namespace: it.Namespace, ResourceKind: it.Kind, ResourceName: it.Name,
				Rule: "image-tag-policy", Severity: "medium",
				Message:  "이미지 태그 정책 위반: " + img,
				Evidence: bad,
			})
		}
	}
	return out
}

