	items := []store.K8sInventoryItem{
		{Kind: "Node", Name: "node-1", StatusObject: map[string]any{"conditions": []any{
			map[string]any{"type": "Ready", "status": "True"},
			map[string]any{"type": "MemoryPressure", "status": "True"},
