	joined := ""
	for _, e := range out[0].Evidence {
		joined += e + "|"
	}
	if !containsSub([]string{joined}, "MemoryPressure") || !containsSub([]string{joined}, "p1") {
		t.Fatalf("evidence should include pressure type + affected pod: %+v", out[0].Evidence)
	}
}

